from functools import lru_cache
# a tree is None (empty) or (left, right); enumerate all non-empty binary tree shapes with n nodes
@lru_cache(None)
def trees(n):
    if n==0: return (None,)
    return tuple((l,r) for k in range(n) for l in trees(k) for r in trees(n-1-k))
def stats(t):  # returns (H in edges, I, L, N)
    l,r=t; kids=[c for c in (l,r) if c is not None]
    if not kids: return (0,0,1,1)
    s=[stats(c) for c in kids]
    return (1+max(x[0] for x in s), 1+sum(x[1] for x in s), sum(x[2] for x in s), 1+sum(x[3] for x in s))
chk={'A':lambda H,I,L,N: L<=I+1,
     'B':lambda H,I,L,N: H+1<=N<=2**(H+1)-1,
     'C':lambda H,I,L,N: H<=I<=2**H-1,
     'D':lambda H,I,L,N: H<=L<=2**(H-1)}
fails={k:None for k in chk}; cnt=0
for n in range(1,12):
    for t in trees(n):
        H,I,L,N=stats(t); cnt+=1
        for k,f in chk.items():
            if not f(H,I,L,N) and fails[k] is None: fails[k]=(H,I,L,N)
print('trees checked:',cnt)
for k in chk: print(k,'always true' if fails[k] is None else 'FALSE, counterexample (H,I,L,N)=%s'%(fails[k],))
# explicit counterexamples for D: path of height 3, perfect tree of height 2
path3=((((None,None),None),None),None)
perf2=(((None,None),(None,None)),((None,None),(None,None)))
for nm,t in (('path H=3',path3),('perfect H=2',perf2)):
    H,I,L,N=stats(t); print(nm,(H,I,L,N),'D holds?',chk['D'](H,I,L,N))
